310	
311	    /**
312	     * Rejects saving {@code owner} when its email's domain is on the disposable-domain blocklist
313	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}). The email is optional: a {@code null} email is left
314	     * untouched. The comparison is case-insensitive on the part after the last {@code '@'}; the
315	     * email has already been lower-cased by {@link #saveOwner(Owner)} before this runs.
316	     *
317	     * @throws DisposableEmailDomainException if the email domain is blocklisted
318	     */
319	    private void assertEmailDomainAllowed(Owner owner) {
320	        String email = owner.getEmail();
321	        if (email == null) {
322	            return;
323	        }
324	        int at = email.lastIndexOf('@');
325	        if (at < 0) {
326	            return;
327	        }
328	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
329	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
330	            throw new DisposableEmailDomainException(domain);
331	        }
332	    }
